import {
    checkCaseStep,
    ensureGuestSession,
    getCase,
    getCases,
    saveCaseProgress
} from '../core/api.js';
import { difficultyLabels } from '../core/labels.js';
import { resetCasePlay, state } from '../core/state.js';
import { getProfile } from '../core/storage.js';
import { announce, emptyState, escapeHtml, loadingState } from '../ui/shell.js';

const LETTERS = ['А', 'Б', 'В', 'Г'];

export async function loadCasesList() {
    const data = await getCases();
    state.cases.list = data.cases || [];
}

export function casesListView() {
    const list = state.cases.list;
    if (list === null) return loadingState('Загружаем кейсы');
    if (!list.length) {
        return emptyState('Кейсов пока нет', 'Загляните позже или откройте текущую версию.', '/', 'На главную');
    }

    return `
        <section>
            <p class="eyebrow">Кейсы</p>
            <h1>Разберите рабочую ситуацию</h1>
            <p class="lede">Ответы проверяются на сервере. В части кейсов путь зависит от выбора.</p>
            <div class="stack">
                ${list.map((item) => `
                    <button class="card" type="button" data-action="open-case" data-case-id="${escapeHtml(item.id)}">
                        <span class="card-title">${escapeHtml(item.title)}</span>
                        <span>${escapeHtml(item.description || '')}</span>
                        <span class="card-meta">
                            ${escapeHtml(difficultyLabels[item.difficulty] || item.difficulty || '')}
                            · ${Number(item.steps_count || 0)} шагов
                        </span>
                    </button>
                `).join('')}
            </div>
        </section>
    `;
}

export async function openCase(caseId) {
    resetCasePlay();
    const profile = getProfile();
    await ensureGuestSession(profile.displayName || '');
    const data = await getCase(caseId);
    const steps = data.steps || [];
    const stepsByNumber = {};
    steps.forEach((step) => {
        stepsByNumber[step.step_number] = step;
    });
    state.cases.current = data.case;
    state.cases.steps = steps;
    state.cases.stepsByNumber = stepsByNumber;
    state.cases.stepNumber = steps[0]?.step_number || 1;
}

export function casePlayView() {
    const session = state.cases;
    const current = session.current;
    if (!current) return casesListView();

    if (session.finished) {
        const total = Math.max(session.answered, session.steps.length);
        const pct = Math.round((session.correctCount / total) * 100);
        const message = pct === 100
            ? 'Идеальный разбор ситуации.'
            : pct >= 50
                ? 'Хороший результат — можно пройти ещё раз.'
                : 'Есть над чем поработать. Пройдите кейс снова.';
        return `
            <section>
                <p class="eyebrow">Кейс завершён</p>
                <h1>${escapeHtml(current.title)}</h1>
                <p class="score" aria-label="${session.correctCount} из ${total}">${session.correctCount}/${total}</p>
                <p class="lede">${escapeHtml(message)}</p>
                <div class="button-row">
                    <button class="button" type="button" data-action="back-cases">К списку</button>
                    <button class="button secondary" type="button" data-action="open-case" data-case-id="${escapeHtml(current.id)}">Пройти снова</button>
                </div>
            </section>
        `;
    }

    const step = session.stepsByNumber[session.stepNumber];
    if (!step) {
        return `
            <section class="state-card">
                <h1>Шаг не найден</h1>
                <button class="button" type="button" data-action="back-cases">К списку</button>
            </section>
        `;
    }

    const answers = (step.options || []).map((option, index) => `
        <button class="answer ${session.feedback ? answerClass(session.feedback, index) : ''}"
                type="button" data-action="case-answer" data-answer="${index}"
                ${session.feedback || state.busy ? 'disabled' : ''}>
            <span class="answer-mark" aria-hidden="true">${LETTERS[index]}</span>
            <span>${escapeHtml(option)}</span>
        </button>
    `).join('');

    return `
        <section>
            <p class="eyebrow">Шаг ${session.stepNumber} · ${session.steps.length} в кейсе</p>
            <h1>${escapeHtml(current.title)}</h1>
            ${current.scenario ? `<p class="lede">${escapeHtml(current.scenario)}</p>` : ''}
            <article class="question-card">
                <h2>${escapeHtml(step.question)}</h2>
                <div class="answers">${answers}</div>
            </article>
            ${session.feedback ? `
                <section class="feedback ${session.feedback.correct ? 'ok' : 'error'}" role="status">
                    <h2>${session.feedback.correct ? '✓ Верно' : '✕ Неверно'}</h2>
                    <p>${escapeHtml(session.feedback.explanation || '')}</p>
                    <button class="button" type="button" data-action="case-next">
                        ${session.feedback.finished ? 'Завершить кейс' : 'Следующий шаг'}
                    </button>
                </section>
            ` : ''}
            <p class="muted"><button class="text-button" type="button" data-action="back-cases">← К списку кейсов</button></p>
        </section>
    `;
}

function answerClass(feedback, index) {
    if (index === feedback.correctIndex) return 'is-correct';
    if (index === feedback.selected && !feedback.correct) return 'is-wrong';
    return '';
}

export async function submitCaseAnswer(answer) {
    if (state.busy || state.cases.feedback) return;
    state.busy = true;
    try {
        const result = await checkCaseStep(state.cases.current.id, state.cases.stepNumber, answer);
        state.cases.answered += 1;
        if (result.correct) state.cases.correctCount += 1;
        state.cases.feedback = { ...result, selected: answer };
        state.cases.pendingNext = result.finished ? null : result.next_step;
        announce(result.correct ? 'Верно' : 'Неверно');
    } finally {
        state.busy = false;
    }
}

export async function advanceCase() {
    const session = state.cases;
    if (!session.feedback) return;
    if (session.feedback.finished || session.pendingNext === null) {
        session.finished = true;
        session.feedback = null;
        try {
            await saveCaseProgress(session.current.id, session.correctCount, true);
        } catch {
            /* local completion still shown */
        }
        return;
    }
    session.stepNumber = session.pendingNext;
    session.pendingNext = null;
    session.feedback = null;
}

export function backToCasesList() {
    resetCasePlay();
}
