const navItems = [
    ['/', 'Домой'],
    ['/learn', 'Учиться'],
    ['/cases', 'Кейсы'],
    ['/profile', 'Профиль']
];

function escapeHtml(value = '') {
    return String(value)
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
}

export { escapeHtml };

function activeNav(route) {
    if (route.startsWith('/quiz') || route.startsWith('/result') || route.startsWith('/start') || route === '/join') {
        return '/';
    }
    if (route.startsWith('/learn')) return '/learn';
    if (route.startsWith('/cases') || route.startsWith('/case')) return '/cases';
    if (route === '/me' || route.startsWith('/profile')) return '/profile';
    if (route.startsWith('/host')) return '';
    return route;
}

export function shell(content, route = '/') {
    const active = activeNav(route);
    const nav = navItems.map(([href, label]) => `
        <a href="/v2${href === '/' ? '/' : href}" data-route="${href}"
           ${active === href ? 'aria-current="page"' : ''}>${label}</a>
    `).join('');

    return `
        <div class="app-shell">
            <header class="topbar">
                <a class="brand" href="/v2/" data-route="/">GLM Quiz</a>
                <a class="host-link" href="/v2/host" data-route="/host">Спикерам</a>
            </header>
            <main id="main" class="page" tabindex="-1">${content}</main>
            <nav class="bottom-nav" aria-label="Основная навигация">${nav}</nav>
        </div>
    `;
}

export function loadingState(message = 'Загружаем…') {
    return `
        <section aria-busy="true" aria-label="${escapeHtml(message)}">
            <p class="eyebrow">${escapeHtml(message)}</p>
            <div class="stack">
                <div class="skeleton"></div>
                <div class="skeleton"></div>
            </div>
        </section>
    `;
}

export function errorState(message, action = 'Повторить', { home = false } = {}) {
    const control = home
        ? `<a class="button" href="/v2/" data-route="/">${escapeHtml(action)}</a>`
        : `<button class="button" type="button" data-action="retry">${escapeHtml(action)}</button>`;
    return `
        <section class="state-card" role="alert">
            <p class="eyebrow">Не удалось продолжить</p>
            <h1>Что-то пошло не так</h1>
            <p>${escapeHtml(message)}</p>
            ${control}
        </section>
    `;
}

export function emptyState(title, text, href = '/', action = 'На главную') {
    return `
        <section class="state-card">
            <p class="eyebrow">Пока пусто</p>
            <h1>${escapeHtml(title)}</h1>
            <p>${escapeHtml(text)}</p>
            <a class="button" href="/v2${href}" data-route="${href}">${escapeHtml(action)}</a>
        </section>
    `;
}

export function announce(message) {
    const node = document.querySelector('#announcer');
    if (node) node.textContent = message;
}
