import { ensureGuestSession, getUserCertificates, saveActionPlan } from '../core/api.js';
import { getProfile, getPreferences, getSession, keys, read, setPreferences, setProfile } from '../core/storage.js';
import { state } from '../core/state.js';
import { escapeHtml } from '../ui/shell.js';

export async function loadProfileExtras() {
    const session = getSession();
    if (!session.userId || !session.token) {
        state.profileExtras.certificates = [];
        return;
    }
    try {
        const data = await getUserCertificates(session.userId);
        state.profileExtras.certificates = data.certificates || data || [];
    } catch {
        state.profileExtras.certificates = [];
    }
}

export function profileView() {
    const profile = getProfile();
    const prefs = getPreferences();
    const history = read(keys.history, []);
    const session = getSession();
    const certificates = state.profileExtras.certificates || [];
    const avg = history.length
        ? Math.round(history.reduce((sum, item) => sum + (item.percentage || 0), 0) / history.length)
        : null;

    return `
        <section>
            <p class="eyebrow">Профиль</p>
            <h1>${escapeHtml(profile.displayName || 'Участник')}</h1>
            <p class="lede">
                ${history.length
                    ? `Завершено проверок в V2: ${history.length}${avg !== null ? ` · средний результат ${avg}%` : ''}.`
                    : 'Пройдите первую проверку — регистрация не обязательна.'}
            </p>

            ${history.length ? `
                <div class="stack">
                    ${history.slice(0, 5).map((item) => `
                        <article class="card static-card">
                            <strong>${item.score}/${item.total} · ${item.percentage}%</strong>
                            <span class="card-meta">${new Date(item.completedAt).toLocaleDateString('ru-RU')} · ${escapeHtml(item.goal || 'quiz')}</span>
                        </article>
                    `).join('')}
                </div>
            ` : ''}

            <h2 class="section-title">Настройки</h2>
            <form class="stack" data-form="profile-settings">
                <div class="field">
                    <label for="profile-name">Как к вам обращаться</label>
                    <input id="profile-name" name="displayName" maxlength="60"
                           autocomplete="name" value="${escapeHtml(profile.displayName || '')}">
                </div>
                <label class="check-row">
                    <input type="checkbox" name="tts" ${prefs.tts ? 'checked' : ''}>
                    Озвучивать вопросы (TTS), если браузер поддерживает
                </label>
                <label class="check-row">
                    <input type="checkbox" name="confidencePrompt" ${prefs.confidencePrompt !== false ? 'checked' : ''}>
                    Спрашивать уверенность перед проверкой ответа (в полной версии)
                </label>
                <label class="check-row">
                    <input type="checkbox" name="sound" ${prefs.sound !== false ? 'checked' : ''}>
                    Звуковые подсказки
                </label>
                <button class="button" type="submit">Сохранить настройки</button>
            </form>

            <h2 class="section-title">План действия</h2>
            <p class="muted">Коротко зафиксируйте, что примените на работе после обучения.</p>
            <form class="stack" data-form="action-plan">
                <div class="field">
                    <label for="action-plan-text">Мой следующий шаг</label>
                    <textarea id="action-plan-text" name="text" rows="3" maxlength="2000"
                              placeholder="Например: проверить порядок передачи смены"></textarea>
                </div>
                <button class="button secondary" type="submit">Сохранить план</button>
                ${state.profileExtras.actionPlanSaved ? '<p class="tip" role="status">План сохранён.</p>' : ''}
            </form>

            <h2 class="section-title">Сертификаты и аккаунт</h2>
            <div class="link-list">
                <a href="/my-certificates.html">Мои сертификаты${certificates.length ? ` (${certificates.length})` : ''}</a>
                <a href="/register.html">Регистрация для сертификата</a>
                <a href="/status.html">Статус сервиса</a>
                <a href="/guide/user">Инструкция участника</a>
                <a href="/v2/host" data-route="/host">Кабинет спикера (V2)</a>
            </div>
            <p class="muted">Сессия: ${session.userId ? 'гость/пользователь активен' : 'ещё не создана'}.</p>
        </section>
    `;
}

export function saveProfileSettings(formData) {
    const displayName = String(formData.get('displayName') || '').trim();
    setProfile({ ...getProfile(), displayName });
    setPreferences({
        tts: formData.get('tts') === 'on',
        confidencePrompt: formData.get('confidencePrompt') === 'on',
        sound: formData.get('sound') === 'on'
    });
    if (displayName) {
        ensureGuestSession(displayName).catch(() => {});
    }
}

export async function submitActionPlan(text) {
    const profile = getProfile();
    await ensureGuestSession(profile.displayName || '');
    await saveActionPlan(text);
    state.profileExtras.actionPlanSaved = true;
}
