import {
    checkAnswer,
    ensureGuestSession,
    getQuestions,
    getSpacedDue,
    getSpacedStats,
    reviewSpacedCard
} from '../core/api.js';
import { labelCategory } from '../core/labels.js';
import { resetLearn, resetQuiz, state } from '../core/state.js';
import { getProfile } from '../core/storage.js';
import { announce, escapeHtml } from '../ui/shell.js';

const LETTERS = ['А', 'Б', 'В', 'Г'];
const QUALITY = [
    { value: 0, label: 'Снова', hint: 'Не вспомнил' },
    { value: 3, label: 'Трудно', hint: 'С трудом' },
    { value: 4, label: 'Хорошо', hint: 'Уверенно' },
    { value: 5, label: 'Легко', hint: 'Сразу' }
];

export async function loadLearnHub() {
    const profile = getProfile();
    await ensureGuestSession(profile.displayName || '');
    try {
        state.learn.stats = await getSpacedStats();
    } catch {
        state.learn.stats = { total_cards: 0, due_today: 0, mature_cards: 0 };
    }
}

export function learnView() {
    const stats = state.learn.stats || {};
    const due = Number(stats.due_today || 0);
    const total = Number(stats.total_cards || 0);

    return `
        <section>
            <p class="eyebrow">Учиться</p>
            <h1>Закрепляйте знания</h1>
            <p class="lede">Интервальные повторения и практика по темам — без перегруза главной страницы.</p>

            <div class="choice-grid learn-grid">
                <button class="card" type="button" data-action="start-review">
                    <span class="card-title">Повторение на сегодня</span>
                    <span>Карточки по алгоритму SM-2. Новые вопросы добавляются автоматически.</span>
                    <span class="card-meta">${due} к повтору · ${total} в колоде</span>
                </button>
                <a class="card" href="/v2/start/training" data-route="/start/training">
                    <span class="card-title">Свободная тренировка</span>
                    <span>10 случайных вопросов с пояснениями.</span>
                    <span class="card-meta">Около 5 минут</span>
                </a>
            </div>

            <h2 class="section-title">Практика по теме</h2>
            <p class="muted">По 7 вопросов из выбранной категории.</p>
            <div class="chip-grid" role="list">
                ${Object.entries({
                    ethics: 'Этика',
                    rights: 'Права',
                    care_standards: 'Уход',
                    safety: 'Безопасность',
                    emergency: 'Экстренное',
                    communication: 'Коммуникация',
                    documentation: 'Документы',
                    quality: 'Качество'
                }).map(([id, label]) => `
                    <button class="chip" type="button" data-action="start-category" data-category="${id}" role="listitem">
                        ${escapeHtml(label)}
                    </button>
                `).join('')}
            </div>
        </section>
    `;
}

export async function startReviewSession() {
    resetLearn();
    state.learn.mode = 'review';
    const profile = getProfile();
    await ensureGuestSession(profile.displayName || '');
    const data = await getSpacedDue(20);
    const cards = [...(data.due || []), ...(data.new || [])];
    if (!cards.length) {
        throw new Error('Пока нет карточек. Пройдите тренировку — вопросы попадут в колоду.');
    }
    state.learn.cards = cards;
    state.learn.index = 0;
    state.learn.finished = false;
}

export function reviewView() {
    const learn = state.learn;
    if (learn.finished) {
        return `
            <section>
                <p class="eyebrow">Повторение</p>
                <h1>Сессия завершена</h1>
                <p class="score" aria-label="${learn.correct} из ${learn.reviewed}">${learn.correct}/${learn.reviewed}</p>
                <p class="lede">Карточки сохранены в расписании повторений.</p>
                <div class="button-row">
                    <a class="button" href="/v2/learn" data-route="/learn">К обучению</a>
                    <button class="button secondary" type="button" data-action="start-review">Ещё раз</button>
                </div>
            </section>
        `;
    }

    const card = learn.cards[learn.index];
    if (!card) return '';
    const progress = Math.round(((learn.index + 1) / learn.cards.length) * 100);
    const answers = (card.options || []).map((option, index) => `
        <button class="answer ${learn.feedback ? answerClass(learn.feedback, index) : ''}"
                type="button" data-action="review-answer" data-answer="${index}"
                ${learn.feedback || state.busy ? 'disabled' : ''}>
            <span class="answer-mark" aria-hidden="true">${LETTERS[index]}</span>
            <span>${escapeHtml(option)}</span>
        </button>
    `).join('');

    return `
        <section>
            <div class="progress-wrap">
                <span>Карточка ${learn.index + 1} из ${learn.cards.length}</span>
                <progress class="progress" max="100" value="${progress}">${progress}%</progress>
            </div>
            <article class="question-card">
                <p class="eyebrow">${escapeHtml(labelCategory(card.category))}</p>
                <h1>${escapeHtml(card.question)}</h1>
                <div class="answers">${answers}</div>
            </article>
            ${learn.feedback ? `
                <section class="feedback ${learn.feedback.correct ? 'ok' : 'error'}" role="status">
                    <h2>${learn.feedback.correct ? '✓ Верно' : '✕ Неверно'}</h2>
                    <p>${escapeHtml(learn.feedback.explanation || 'Пояснение появится после оценки.')}</p>
                    ${learn.awaitingQuality ? `
                        <p class="muted">Насколько легко было ответить?</p>
                        <div class="button-row quality-row">
                            ${QUALITY.map((item) => `
                                <button class="button secondary" type="button"
                                        data-action="review-quality" data-quality="${item.value}"
                                        title="${escapeHtml(item.hint)}">${escapeHtml(item.label)}</button>
                            `).join('')}
                        </div>
                    ` : ''}
                </section>
            ` : ''}
        </section>
    `;
}

function answerClass(feedback, index) {
    if (index === feedback.correctIndex) return 'is-correct';
    if (index === feedback.selected && !feedback.correct) return 'is-wrong';
    return '';
}

export async function submitReviewAnswer(answer) {
    if (state.busy || state.learn.feedback) return;
    state.busy = true;
    try {
        const card = state.learn.cards[state.learn.index];
        const feedback = await checkAnswer(card.id, answer);
        state.learn.feedback = { ...feedback, selected: answer };
        state.learn.awaitingQuality = true;
        if (feedback.correct) state.learn.correct += 1;
        announce(feedback.correct ? 'Верно' : 'Неверно');
    } finally {
        state.busy = false;
    }
}

export async function submitReviewQuality(quality) {
    if (state.busy || !state.learn.awaitingQuality) return;
    state.busy = true;
    try {
        const card = state.learn.cards[state.learn.index];
        await reviewSpacedCard(card.id, Number(quality));
        state.learn.reviewed += 1;
        state.learn.awaitingQuality = false;
        state.learn.feedback = null;
        if (state.learn.index + 1 < state.learn.cards.length) {
            state.learn.index += 1;
        } else {
            state.learn.finished = true;
        }
    } finally {
        state.busy = false;
    }
}

export async function startCategoryPractice(category) {
    resetQuiz('category');
    state.goal = 'category';
    const profile = getProfile();
    const [data] = await Promise.all([
        getQuestions(),
        ensureGuestSession(profile.displayName || '')
    ]);
    const valid = (data.questions || []).filter((question) =>
        question.category === category
        && Number.isFinite(question.id)
        && question.question
        && Array.isArray(question.options)
        && question.options.length === 4
    );
    if (!valid.length) {
        throw new Error(`В теме «${labelCategory(category)}» пока нет вопросов.`);
    }
    const shuffled = [...valid].sort(() => Math.random() - 0.5);
    state.questions = shuffled.slice(0, Math.min(7, shuffled.length));
    state.index = 0;
    state.score = 0;
    state.answers = [];
    state.feedback = null;
}
