import { labelCategory } from '../core/labels.js';
import { state } from '../core/state.js';
import { addHistory, keys, read, write } from '../core/storage.js';
import { escapeHtml } from '../ui/shell.js';

function weakCategory() {
    const misses = new Map();
    state.answers.filter((answer) => !answer.correct).forEach((answer) => {
        misses.set(answer.category, (misses.get(answer.category) || 0) + 1);
    });
    return [...misses.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] || null;
}

export function recordResult() {
    const percentage = Math.round((state.score / state.questions.length) * 100);
    addHistory({
        score: state.score,
        total: state.questions.length,
        percentage,
        goal: state.goal,
        completedAt: new Date().toISOString()
    });
    const onboarding = read(keys.onboarding, {});
    write(keys.onboarding, { ...onboarding, result: true });
}

export function resultView() {
    const total = state.questions.length;
    if (!total) {
        return `
            <section class="state-card">
                <h1>Результат не найден</h1>
                <p>Начните новую проверку знаний с главной страницы.</p>
                <a class="button" href="/v2/" data-route="/">На главную</a>
            </section>
        `;
    }

    const percentage = Math.round((state.score / total) * 100);
    const weak = weakCategory();
    const errors = state.answers.filter((answer) => !answer.correct);
    const saved = state.lastError
        ? '<p class="error-banner">Результат показан, но сервер не смог сохранить его. Локальная история сохранена.</p>'
        : '';

    return `
        <section>
            <p class="eyebrow">Готово</p>
            <h1>${percentage >= 80 ? 'Отличная работа' : 'Проверка завершена'}</h1>
            <p class="score" aria-label="${state.score} из ${total}">${state.score}/${total}</p>
            <p class="lede">${percentage}% правильных ответов.</p>
            ${saved}
            ${weak ? `<p class="tip">Подсказка 3 из 3: стоит повторить тему «${escapeHtml(labelCategory(weak))}».</p>` : ''}
            <div class="button-row">
                ${errors.length ? '<button class="button" type="button" data-action="retry-errors">Повторить ошибки</button>' : '<a class="button" href="/v2/cases" data-route="/cases">Перейти к кейсам</a>'}
                <a class="button secondary" href="/v2/learn" data-route="/learn">К обучению</a>
                <a class="button secondary" href="/v2/" data-route="/">Другая цель</a>
            </div>
            <details>
                <summary>Посмотреть ответы</summary>
                <ul>
                    ${state.answers.map((answer) => `
                        <li>${answer.correct ? 'Верно' : 'Ошибка'}: ${escapeHtml(answer.question)}</li>
                    `).join('')}
                </ul>
            </details>
        </section>
    `;
}
